/// <summary>
/// MPJ_3338_AMEXCustomerPaymentProcessing
/// Data contract class for customer payment proposal batch job <c>METAMEXCustPaymeProposalService</c>
/// </summary>
[DataContractAttribute, SysOperationContractProcessingAttribute(classStr(METAMEXCustPaymProposalUIBuilder))]
class METAMEXCustPaymProposalContract
{
    private METAMEXRegion           region;
    private CustAccountStatement    paymentRun;
    private CustPaymMode            paymMode;
    private LedgerJournalNameId     journalName;
    private boolean                 createJournal;
    private str                     companies;
    private LedgerJournalTable      JournalTable;
    private FromDate                fromDate;
    private ToDate                  toDate;
    private boolean                 generatePaymFile;
    
    
}

